  {"question": "Which organizations were included in the AIS corpus extension, and what clustering method was used for VOSViewer figures?", "answer": "Organizations like Anthropic and DeepMind were included; VOSViewer used clustering based on total link strength.", "evidence": [{"page": 37, "quote": "· Anthropic (https://www.anthropic.com/)\n· DeepMind (https://deepmind.google/)"}, {"page": 42, "quote": "Nodes are colored by the clustering algorithm of VOSViewer, which groups nodes together based on their total link strength."}]},
  {"question": "According to arXiv 2603.14495, what is BERTopic and how are clusters labeled?", "answer": "BERTopic clusters documents using cosine distance and labels clusters with class-based tf-idf ranking.", "evidence": [{"page": 42, "quote": "BERTopic clusters and colors each document based on its internal topic model that uses cosine distance between documents to calculate their similarity. Each cluster of documents is assigned a descriptive label using class-based tf-idf ranking over the terms appearing in each cluster."}]},
  {"question": "What does Supplementary Figure 9 in arXiv 2603.14495 show about semantic convergence between AIE and AIS?", "answer": "It shows increasing similarity, with AIS becoming more similar to AIE.", "evidence": [{"page": 42, "quote": "Supplementary Figure 9 shows that the similarity of document embeddings between the corpora are increasing over time, with the documents in AIS becoming more similar to the average embedding of the AIE corpus - as opposed to the AIE documents becoming more similar to the average embedding of the AIS corpus."}]},
  {"question": "How are terms selected for VOSViewer networks in arXiv 2603.14495?", "answer": "Only terms occurring at least four times in a corpus are selected.", "evidence": [{"page": 42, "quote": "Only terms that occur at least four times in a corpus were selected for the network."}]},
  {"question": "Which dimensionality reduction technique is used for BERTopic visualizations in arXiv 2603.14495?", "answer": "UMAP is used to reduce embeddings to two dimensions.", "evidence": [{"page": 42, "quote": "As embeddings are very high dimensional, we used the UMAP algorithm to reduce each embedding to two dimensions [MHM18]."}]},
  {"question": "Which tool was used to generate Supplementary Figures 10 to 12 in arXiv 2603.14495?", "answer": "VOSViewer was used for these figures.", "evidence": [{"page": 42, "quote": "This section provides a number of figures produced with the VOSViewer tool (Supplementary Figures 10 to 12)"}]}
]}
